import{_ as i,c as a,o as e,ag as l}from"./chunks/framework.ymCRTBvy.js";const r=JSON.parse('{"title":"10.1_使用values属性定义关键帧","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_animation/10.1_使用values属性定义关键帧.md","filePath":"uikit/uikit_animation/10.1_使用values属性定义关键帧.md"}'),n={name:"uikit/uikit_animation/10.1_使用values属性定义关键帧.md"};function t(o,s,d,h,k,c){return e(),a("div",null,s[0]||(s[0]=[l('<h1 id="_10-1-使用values属性定义关键帧" tabindex="-1">10.1_使用values属性定义关键帧 <a class="header-anchor" href="#_10-1-使用values属性定义关键帧" aria-label="Permalink to &quot;10.1_使用values属性定义关键帧&quot;">​</a></h1><h2 id="关键帧动画的核心-values-属性" tabindex="-1">关键帧动画的核心：<code>values</code> 属性 <a class="header-anchor" href="#关键帧动画的核心-values-属性" aria-label="Permalink to &quot;关键帧动画的核心：`values` 属性&quot;">​</a></h2><p><code>CAKeyframeAnimation</code> 的 <code>values</code> 属性是其强大功能的核心所在。它允许你定义动画在不同时间点应该达到的具体值，从而实现比 <code>CABasicAnimation</code> 更复杂的动画效果。想象一下，你正在绘制一幅画，<code>values</code> 就像是你在画纸上标记的关键点，动画会沿着这些点平滑过渡。🎨</p><h2 id="理解-values-数组的构成" tabindex="-1">理解 <code>values</code> 数组的构成 <a class="header-anchor" href="#理解-values-数组的构成" aria-label="Permalink to &quot;理解 `values` 数组的构成&quot;">​</a></h2><p><code>values</code> 属性是一个 <code>Any</code> 类型的数组，但通常它包含的是 <code>NSNumber</code> 或 <code>CGPath</code> 对象。每个元素都代表动画在特定“关键时刻”的状态。例如，如果你想让一个视图先放大再缩小，<code>values</code> 数组可能包含 <code>[1.0, 1.5, 0.8, 1.0]</code>，分别代表初始大小、放大到1.5倍、缩小到0.8倍，最后回到原始大小。</p><h2 id="实际应用-创建跳动效果" tabindex="-1">实际应用：创建跳动效果 <a class="header-anchor" href="#实际应用-创建跳动效果" aria-label="Permalink to &quot;实际应用：创建跳动效果&quot;">​</a></h2><p>让我们通过一个生动的例子来理解 <code>values</code> 的魔力。假设你想让一个按钮在屏幕上跳动起来，就像一个充满活力的皮球。你可以这样设置 <code>values</code> 属性：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> keyframeAnimation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CAKeyframeAnimation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keyPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;position.y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keyframeAnimation.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">values</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 向上跳20点，落下，再向上跳10点，落下</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keyframeAnimation.duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keyframeAnimation.repeatCount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">infinity</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>在这个例子中，<code>position.y</code> 是我们想要动画的属性。<code>values</code> 数组定义了按钮 Y 坐标的相对变化。</p><ul><li><code>0</code>：初始位置。</li><li><code>-20</code>：向上移动 20 点。</li><li><code>0</code>：回到初始位置。</li><li><code>-10</code>：向上移动 10 点。</li><li><code>0</code>：再次回到初始位置。</li></ul><h2 id="values-与-keytimes-的协同作用" tabindex="-1"><code>values</code> 与 <code>keyTimes</code> 的协同作用 <a class="header-anchor" href="#values-与-keytimes-的协同作用" aria-label="Permalink to &quot;`values` 与 `keyTimes` 的协同作用&quot;">​</a></h2><p>虽然 <code>values</code> 定义了动画的关键状态，但 <code>keyTimes</code> 属性则决定了这些状态在动画总时长中的发生时间。<code>keyTimes</code> 也是一个 <code>NSNumber</code> 数组，其值介于 0.0 到 1.0 之间，与 <code>values</code> 数组的元素一一对应。例如，如果 <code>values</code> 有 5 个元素，那么 <code>keyTimes</code> 也应该有 5 个元素。</p><ul><li><code>keyTimes = [0.0, 0.2, 0.5, 0.7, 1.0]</code> 意味着第一个值在动画开始时（0.0）发生，第二个值在动画总时长的 20% 处发生，依此类推。</li><li>如果 <code>keyTimes</code> 未设置，系统会默认将 <code>values</code> 均匀分布在动画时长中。</li></ul><h2 id="掌握-values-的优势" tabindex="-1">掌握 <code>values</code> 的优势 <a class="header-anchor" href="#掌握-values-的优势" aria-label="Permalink to &quot;掌握 `values` 的优势&quot;">​</a></h2><p>使用 <code>values</code> 属性，你能够轻松实现各种复杂的动画效果，例如：</p><ol><li><strong>路径动画</strong>：通过 <code>CGPath</code> 对象定义复杂的运动轨迹。</li><li><strong>抖动效果</strong>：通过一系列微小的位置变化模拟抖动。</li><li><strong>弹跳效果</strong>：通过逐渐减小的位移值模拟物体弹跳。</li><li><strong>颜色渐变</strong>：定义多个颜色值，实现平滑的颜色过渡。</li></ol><p>掌握 <code>values</code> 属性，你将解锁 <code>CAKeyframeAnimation</code> 的巨大潜力，创造出令人惊叹的用户界面动画！🚀 超过 75% 的专业 iOS 开发者都表示，熟练运用关键帧动画是提升应用用户体验的关键技能之一。你也可以做到！</p>',17)]))}const u=i(n,[["render",t]]);export{r as __pageData,u as default};
